from __future__ import annotations
from itertools import product
from typing import Dict, List, Tuple


def parity_memory(word: Tuple[str, ...]) -> int:
    return word.count("a") % 2


def main() -> None:
    classes: Dict[int, List[str]] = {0: [], 1: []}
    for length in range(5):
        for word in product(("a", "b"), repeat=length):
            classes[parity_memory(word)].append("".join(word) or "ε")
    for state, words in classes.items():
        print(f"Observable class {state}: {words}")


if __name__ == "__main__":
    main()

from __future__ import annotations
from typing import Callable, Sequence, Tuple, TypeVar

T = TypeVar("T")


def targeted_forgetting(word: Sequence[T], retain: Callable[[T], bool]) -> Tuple[T, ...]:
    return tuple(x for x in word if retain(x))


def main() -> None:
    keep = lambda event: event in {"WARN", "ERROR"}
    first = ("INFO", "WARN", "INFO", "ERROR")
    second = ("WARN", "ERROR")
    print(targeted_forgetting(first, keep))
    print("Same quotient class:", targeted_forgetting(first, keep) == targeted_forgetting(second, keep))


if __name__ == "__main__":
    main()

from __future__ import annotations
from typing import Callable, Dict, Hashable, Tuple, TypeVar

S = TypeVar("S", bound=Hashable)


def first_collision(generator: S, identity: S, multiply: Callable[[S, S], S], bound: int) -> Tuple[int, int, S]:
    seen: Dict[S, int] = {}
    state = identity
    for exponent in range(bound + 1):
        if state in seen:
            return seen[state], exponent, state
        seen[state] = exponent
        state = multiply(state, generator)
    raise ValueError("The supplied bound does not cover the finite orbit")


def main() -> None:
    print(first_collision(2, 0, lambda x, y: (x + y) % 5, 5))


if __name__ == "__main__":
    main()

