from __future__ import annotations
from typing import Callable, Sequence, Tuple, TypeVar
T = TypeVar("T")

def stream_filter(word: Sequence[T], retain: Callable[[T], bool]) -> Tuple[T, ...]:
    """Compute the targeted-forgetting projection."""
    return tuple(symbol for symbol in word if retain(symbol))

from __future__ import annotations
from typing import Callable, Dict, Hashable, Tuple, TypeVar
S = TypeVar("S", bound=Hashable)

def bounded_unary_collision(generator: S, identity: S, multiply: Callable[[S, S], S], cardinality: int) -> Tuple[int, int, S]:
    """Return i < j <= cardinality with equal powers."""
    first: Dict[S, int] = {}
    state = identity
    for j in range(cardinality + 1):
        if state in first:
            return first[state], j, state
        first[state] = j
        state = multiply(state, generator)
    raise RuntimeError("Inconsistent cardinality bound")

from __future__ import annotations
from collections import deque
from typing import Callable, Dict, Hashable, Mapping, Sequence, Set, Tuple, TypeVar
A = TypeVar("A", bound=Hashable)
S = TypeVar("S", bound=Hashable)

def explore_observable_quotient(alphabet: Sequence[A], images: Mapping[A, S], identity: S, multiply: Callable[[S, S], S]) -> Tuple[Set[S], Dict[Tuple[S, A], S]]:
    """Enumerate reachable states and the induced right-action graph."""
    reached: Set[S] = {identity}
    edges: Dict[Tuple[S, A], S] = {}
    queue = deque([identity])
    while queue:
        state = queue.popleft()
        for letter in alphabet:
            nxt = multiply(state, images[letter])
            edges[(state, letter)] = nxt
            if nxt not in reached:
                reached.add(nxt)
                queue.append(nxt)
    return reached, edges

